using System.ComponentModel.DataAnnotations;
using Microsoft.AspNetCore.Http;

namespace MineSafety.Api.Dtos;

// ---------- Requests (sent by the app) ----------

// Body for POST /api/reports. The phone sends this straight away, or later once it has signal again.
public class CreateReportRequest
{
    // Generated by the phone when the report is first created and sent unchanged on every retry.
    // This is how the server recognises a report it has already received.
    [Required]
    public Guid ClientReportId { get; set; }

    // Send either typeCode ("INCIDENT", "HAZARD" or "NEAR_MISS") or incidentTypeId.
    public string? TypeCode { get; set; }
    public int? IncidentTypeId { get; set; }

    [Required]
    public int LocationId { get; set; } // must be one of the reporter's assigned locations

    // Can be empty when the report has a voice note instead of typed text.
    [MaxLength(4000)]
    public string? Description { get; set; }

    // When it happened, in UTC, for example "2026-10-19T08:30:00Z".
    [Required]
    public DateTime OccurredAt { get; set; }

    // How many photos and voice notes the phone will upload after this report (0 if none).
    // The evidence is complete once all of them have arrived. Until then nobody can approve
    // the report, and a Supervisor's own report is approved automatically at that point.
    [Range(0, 50)]
    public int? ExpectedImageCount { get; set; }
    [Range(0, 50)]
    public int? ExpectedVoiceNoteCount { get; set; }
}

// Body for PUT /api/reports/5. The reporter can edit their report while it is still Pending Review.
public class UpdateReportRequest
{
    public string? TypeCode { get; set; }
    public int? IncidentTypeId { get; set; }

    [Required]
    public int LocationId { get; set; }

    [MaxLength(4000)]
    public string? Description { get; set; }

    [Required]
    public DateTime OccurredAt { get; set; }
}

// Body for POST /api/supervisor/reports/5/review.
public class CreateReviewRequest
{
    // "APPROVE" or "DENY" ("APPROVED" and "DENIED" also work).
    [Required]
    public string Decision { get; set; } = "";

    // Required when denying. The value can also be sent as "comment".
    [MaxLength(1000)]
    public string? Reason { get; set; }

    [MaxLength(1000)]
    public string? Comment { get; set; }
}

// Form fields for POST /api/reports/5/attachments (multipart/form-data).
public class UploadAttachmentRequest
{
    [Required]
    public IFormFile File { get; set; } = null!;

    // "PHOTO" (or "IMAGE") or "VOICE_NOTE".
    [Required]
    public string AttachmentType { get; set; } = "";

    // The phone's own ID for this file, for example "image-12". Uploading with the same ID again
    // returns the original attachment. Without an ID, an identical file on the same report is
    // recognised by its SHA-256 hash instead. The value can also be sent as "localAttachmentId".
    [MaxLength(100)]
    public string? ClientAttachmentId { get; set; }

    [MaxLength(100)]
    public string? LocalAttachmentId { get; set; }

    public DateTime? CapturedAt { get; set; }
}

// ---------- Responses (sent by the API) ----------

// One row in a report list (My Reports, the review queue and the incident list).
public class ReportSummaryDto
{
    public int ReportId { get; set; }
    public string ReportNumber { get; set; } = "";     // for example MS-2026-00042
    public Guid ClientReportId { get; set; }           // lets the phone match this to its local copy
    public string TypeCode { get; set; } = "";         // INCIDENT, HAZARD or NEAR_MISS
    public string IncidentType { get; set; } = "";     // display name: Incident, Hazard or Near Miss
    public bool IsUrgent { get; set; }
    public int LocationId { get; set; }
    public string LocationCode { get; set; } = "";
    public string LocationName { get; set; } = "";
    public string StatusCode { get; set; } = "";       // PENDING_REVIEW, APPROVED or DENIED
    public string Status { get; set; } = "";           // display name
    public DateTime? StatusUpdatedAt { get; set; }     // when the status last changed
    public string? ReviewReason { get; set; }          // the reason given when the report was denied
    public string ReporterName { get; set; } = "";
    public DateTime OccurredAt { get; set; }
    public DateTime? SubmittedAt { get; set; }
    public int ImageCount { get; set; }                // photos received so far
    public int VoiceNoteCount { get; set; }            // voice notes received so far
    public int? ExpectedImageCount { get; set; }       // photos the phone said it would send
    public int? ExpectedVoiceNoteCount { get; set; }   // voice notes the phone said it would send
    public bool EvidenceComplete { get; set; }         // true once everything expected has arrived
    public bool AutoApproved { get; set; }             // approved automatically (a Supervisor's own report)
}

// The full report, used on the report detail screen.
public class ReportDetailDto : ReportSummaryDto
{
    public int IncidentTypeId { get; set; }
    public int ReporterAccountId { get; set; }
    public string ReporterWorkerId { get; set; } = "";
    public string Description { get; set; } = "";
    public DateTime CreatedAt { get; set; }
    public DateTime? UpdatedAt { get; set; }
    public List<ReviewDto> Reviews { get; set; } = new();
    public List<AttachmentDto> Attachments { get; set; } = new();

    // Safety Officers only: a link to this report on the web dashboard.
    public string? DashboardUrl { get; set; }

    // What the current user is allowed to do, so the app knows which buttons to show.
    public bool CanEdit { get; set; }
    public bool CanWithdraw { get; set; }
    public bool CanReview { get; set; }
}

// A single report is always returned wrapped like this: { "report": { ... } }
public class ReportEnvelope
{
    public ReportDetailDto Report { get; set; } = new();
}

// Returned by POST /api/reports.
public class SubmitReportResponse
{
    // False when the report was newly saved (201), true when it had already been received (200).
    // In both cases the phone can mark its local copy as synced.
    public bool AlreadyExisted { get; set; }
    public ReportDetailDto Report { get; set; } = new();
}

// A supervisor's decision on a report.
public class ReviewDto
{
    public int ReviewId { get; set; }
    public string Decision { get; set; } = "";         // APPROVED or DENIED
    public string? Comment { get; set; }
    public string ReviewerName { get; set; } = "";
    public DateTime ReviewedAt { get; set; }
}

// Information about an uploaded file. The server path is never included;
// the file itself is downloaded from GET /api/attachments/{id}.
public class AttachmentDto
{
    public int AttachmentId { get; set; }
    public string AttachmentType { get; set; } = "";   // PHOTO or VOICE_NOTE
    public string OriginalFileName { get; set; } = "";
    public string MimeType { get; set; } = "";
    public long SizeBytes { get; set; }
    public DateTime UploadedAt { get; set; }
}

// Returned by POST /api/reports/5/attachments.
public class UploadAttachmentResponse
{
    public bool AlreadyExisted { get; set; }           // true when the same file was already uploaded
    public AttachmentDto Attachment { get; set; } = new();

    // The report's state after this upload. For example, a Supervisor's report
    // becomes APPROVED when its last expected file arrives.
    public string ReportStatusCode { get; set; } = "";
    public bool EvidenceComplete { get; set; }
}

// One line of the stuck Supervisor reports clean-up (see MaintenanceController).
public class StuckReportDto
{
    public int ReportId { get; set; }
    public string ReportNumber { get; set; } = "";
    public string ReporterWorkerId { get; set; } = "";
    public string LocationName { get; set; } = "";
    public string TypeCode { get; set; } = "";
    public DateTime? SubmittedAt { get; set; }
    public int? ExpectedImageCount { get; set; }
    public int? ExpectedVoiceNoteCount { get; set; }
    public int ImageCount { get; set; }
    public int VoiceNoteCount { get; set; }

    // APPROVED, WOULD_APPROVE, WAITING_FOR_EVIDENCE or NEEDS_CONFIRMATION
    public string Action { get; set; } = "";
    public string Explanation { get; set; } = "";
}

// Body for POST /api/admin/maintenance/stuck-supervisor-reports.
public class StuckReportsRequest
{
    // True (the default) only lists what would happen and changes nothing.
    public bool DryRun { get; set; } = true;

    // Reports created before the AddEvidenceTracking migration have no expected counts, so the server can't tell
    // whether evidence is still missing. They are only approved if their ID is listed here,
    // after someone has checked them (for example, the supervisor's phone has nothing left to upload).
    public List<int> ConfirmLegacyReportIds { get; set; } = new();
}

// One entry in a report's audit history.
public class AuditEntryDto
{
    public int AuditLogId { get; set; }
    public string Action { get; set; } = "";           // CREATED, EDITED, WITHDRAWN, APPROVED, DENIED, ATTACHMENT_ADDED, ...
    public string ActorName { get; set; } = "";
    public DateTime ActionAt { get; set; }
    public string? OldValueJson { get; set; }
    public string? NewValueJson { get; set; }
}

// Dropdown data for report types.
public class IncidentTypeDto
{
    public int IncidentTypeId { get; set; }
    public string TypeCode { get; set; } = "";
    public string TypeName { get; set; } = "";
    public bool TriggersImmediateAlert { get; set; }
}

// Dropdown data for report statuses.
public class ReportStatusDto
{
    public int StatusId { get; set; }
    public string StatusCode { get; set; } = "";
    public string StatusName { get; set; } = "";
    public bool IsTerminal { get; set; }
}
